ES6の場合
<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<title>for文を繰り返し</title>
</head>
<body>
<h1>数字の合計を求めるプログラム</h1>
<p>ボタンを押して数字を入力してください。</p>
<p><button id="calculateButton">合計を求める</button></p>
<h2 id="ans">ここに結果を表示</h2>
<script>
const result = () => {
  let maxNum = prompt('1以上の整数を半角数字で入力してください。');
  maxNum = parseInt(maxNum);
  let total = 0;
  const element = document.querySelector('#ans');

  if (maxNum < 1 || isNaN(maxNum)) {
    element.textContent = '計算できません。';
  } else {
    for (let i = 1; i <= maxNum; i++) {
      total += i;
    }
    element.textContent = `0に入力された数字「${maxNum}」までを1から加算した合計は「${total}」です。`;
  }
};

document.querySelector('#calculateButton').addEventListener('click', result);
</script>
</body>
</html>
