<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>消費税合算後の支払金額を求める</title>
</head>
<body>
<script>
// 消費税権さんの初期値
let price = prompt('購入単価を入力してください。');
price = parseInt(price);
let piece = prompt('購入個数を入力してください。');
piece = parseInt(piece);
const taxRate = 0.1;
let total = 0;
let message = '';

// 演算（処理）
total = (price * piece) + (price * piece * taxRate);
total = Math.round(total);

message = `単価${price}円の商品を${piece}個購入したとき、消費税合算後の支払金額は${total}円です。`;

// 出力（コンソールに表示）
console.log(message);

// ブラウザに表示
document.write(message);
</script>
</body>
</html>



    confirm() で確認


「男性」か「女性」かを確認する
<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>BMIの値を求める</title>
</head>
<body>
<script>
  // ユーザーからの入力を受け取る
  let weight = prompt('体重を kg 単位で入力してください：');
  let height = prompt('身長を cm 単位で入力してください：');

  // 性別を確認（OK なら 男性、Cancel なら 女性）
  let isMale = confirm('性別が男性であれば「OK」、女性であれば「キャンセル」をクリックしてください。');
  let gender = isMale ? '男性' : '女性';

  // 文字列を数値に変換
  weight = parseFloat(weight);
  height = parseFloat(height) / 100;  // cm → m

  // 入力チェック
  if (isNaN(weight) || isNaN(height) || weight <= 0 || height <= 0) {
    console.log('正しい数値を入力してください。');
  } else {
    // BMI 計算
    let bmi = weight / (height * height);

    // コンソールに結果を表示
    console.log(`=== 結果 ===`);
    console.log(`性別：${gender}`);
    console.log(`体重：${weight} kg`);
    console.log(`身長：${(height * 100).toFixed(1)} cm`);
    console.log(`BMI：${bmi.toFixed(2)}`);

    // BMIの判定
    if (bmi < 18.5) {
      console.log(`判定：低体重（やせ型）`);
    } else if (bmi < 25) {
      console.log(`判定：普通体重`);
    } else if (bmi < 30) {
      console.log(`判定：肥満（1度）`);
    } else {
      console.log(`判定：高度肥満`);
    }
  }
</script>
</body>
</html>
